Tìm ${x}$ biết $9 x^{2} - 9=0$ 
\choice
{  $x=2$ hoặc $x=-5$ }
   { \True   $x=1$ hoặc $x=-1$ }
     {  $x=0$ hoặc $x=-5$ }
    {  $x=-3$ hoặc $x=-2$ }
\loigiai{
$9 x^{2} - 9=\left(3 x - 3\right) \left(3 x + 3\right)=0$\\
Do đó $x=1$ hoặc $x=-1$
}\end{ex}

